import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"06-2 智能合约面试自测：先说人话，再说术语","description":"","frontmatter":{},"headers":[],"relativePath":"06-career/interview.md","filePath":"06-career/interview.md","lastUpdated":1791601077000}'),i={name:"06-career/interview.md"};function l(n,e,s,d,p,c){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="_06-2-智能合约面试自测-先说人话-再说术语" tabindex="-1">06-2 智能合约面试自测：先说人话，再说术语 <a class="header-anchor" href="#_06-2-智能合约面试自测-先说人话-再说术语" aria-label="Permalink to &quot;06-2 智能合约面试自测：先说人话，再说术语&quot;">​</a></h1><blockquote><p><strong>适用阶段</strong>：已经完成 Counter、权限实验和 Escrow 本地测试。这里不是要求背答案，而是练习把一个技术概念说给没有区块链背景的人听。</p><p><strong>使用方法</strong>：先盖住“参考解释”，自己回答 30 秒，再对照答案补充遗漏。如果回答不出来，点击对应课程链接重做实验即可。</p></blockquote><h2 id="第一组-钱包、账户、交易-最容易混淆" tabindex="-1">第一组：钱包、账户、交易（最容易混淆） <a class="header-anchor" href="#第一组-钱包、账户、交易-最容易混淆" aria-label="Permalink to &quot;第一组：钱包、账户、交易（最容易混淆）&quot;">​</a></h2><h3 id="_1-eoa-和合约账户有什么不同" tabindex="-1">1. EOA 和合约账户有什么不同？ <a class="header-anchor" href="#_1-eoa-和合约账户有什么不同" aria-label="Permalink to &quot;1. EOA 和合约账户有什么不同？&quot;">​</a></h3><p><strong>通俗说法：</strong> EOA 可以理解为“有密钥的用户账户”，合约账户则对应一份部署好的程序与它保存的状态。</p><p><strong>技术解释：</strong> 传统 EOA 主要由私钥签名发起交易；合约账户由链上代码控制其行为。智能账户等新机制让实际账户模型更加丰富，初学时先掌握这两类最常见概念。</p><p><strong>常见误区：</strong> “合约账户必须有人登录才能执行”不正确。合约通常在收到外部交易或其他合约的调用时执行，本身不能像 Celery 一样自行定时运行。</p><p>练习入口：<a href="/00-start/">从钱包和账户开始</a>。</p><h3 id="_2-钱包里真的存着-eth-吗" tabindex="-1">2. 钱包里真的存着 ETH 吗？ <a class="header-anchor" href="#_2-钱包里真的存着-eth-吗" aria-label="Permalink to &quot;2. 钱包里真的存着 ETH 吗？&quot;">​</a></h3><p>不是。链上状态记录账户资产，钱包管理密钥、查看余额和发起签名请求。卸载钱包不会清空链上资产，但丢失唯一的密钥恢复方式可能导致无法再控制资产。</p><p><strong>一句话复述：</strong> 钱包是查看和控制链上账户的工具，不是放钱的硬盘文件夹。</p><h3 id="_3-为什么链上写入要消耗-gas" tabindex="-1">3. 为什么链上写入要消耗 Gas？ <a class="header-anchor" href="#_3-为什么链上写入要消耗-gas" aria-label="Permalink to &quot;3. 为什么链上写入要消耗 Gas？&quot;">​</a></h3><p>因为区块链执行和保存状态需要网络参与者投入资源，需要计量和限制滥用。Gas 是资源计量；ETH 是支付资产，它们不是同一个单位。</p><p><strong>类比：</strong> 你运行 Flask 需要服务器资源；在以太坊中，执行交易需要按网络的收费规则付费。</p><h3 id="_4-拿到交易哈希-是不是说明付款成功" tabindex="-1">4. 拿到交易哈希，是不是说明付款成功？ <a class="header-anchor" href="#_4-拿到交易哈希-是不是说明付款成功" aria-label="Permalink to &quot;4. 拿到交易哈希，是不是说明付款成功？&quot;">​</a></h3><p>不是。<strong>签名、广播、被网络接收、进入区块、执行成功、满足业务确认要求</strong>是不同的步骤。</p><p>一个后端服务通常需要进一步查交易回执的执行状态、校验目标网络和合约，并按风险决定等待多少确认。链重组也应纳入业务设计。</p><p>练习入口：<a href="/02-evm/">交易、EVM 与 Gas</a>。</p><h2 id="第二组-solidity-语法与数据-必须亲手做过" tabindex="-1">第二组：Solidity 语法与数据（必须亲手做过） <a class="header-anchor" href="#第二组-solidity-语法与数据-必须亲手做过" aria-label="Permalink to &quot;第二组：Solidity 语法与数据（必须亲手做过）&quot;">​</a></h2><h3 id="_5-public、private、external-分别是什么意思" tabindex="-1">5. public、private、external 分别是什么意思？ <a class="header-anchor" href="#_5-public、private、external-分别是什么意思" aria-label="Permalink to &quot;5. public、private、external 分别是什么意思？&quot;">​</a></h3><ul><li><code>public</code>：对状态变量通常生成公开 getter；公开函数可被外部调用。</li><li><code>private</code>：限制在声明它的合约中进行 Solidity 代码层面的直接访问，<strong>不表示数据加密</strong>。</li><li><code>external</code>：函数面向合约外部调用，区别于内部直接调用语义。</li></ul><p><strong>常见误区：</strong> <code>owner</code> 声明成 public，并不会让所有人都可以修改它；也不会自动阻止普通用户调用其他没有加权限的函数。</p><h3 id="_6-view、pure、payable-有何区别" tabindex="-1">6. view、pure、payable 有何区别？ <a class="header-anchor" href="#_6-view、pure、payable-有何区别" aria-label="Permalink to &quot;6. view、pure、payable 有何区别？&quot;">​</a></h3><ul><li><code>view</code>：函数不能修改链上状态，可读取合约状态。</li><li><code>pure</code>：不能读也不能修改合约状态。</li><li><code>payable</code>：函数允许随调用携带原生资产。</li></ul><p>例如 Counter 的 <code>count()</code> 是只读 getter；<code>increase()</code> 负责修改状态。<code>payable</code> 不等于安全收款，还需要考虑提款权限与失败模式。</p><p>练习入口：<a href="/01-solidity/">Solidity 变量和函数</a>。</p><h3 id="_7-storage、memory、calldata-是什么" tabindex="-1">7. storage、memory、calldata 是什么？ <a class="header-anchor" href="#_7-storage、memory、calldata-是什么" aria-label="Permalink to &quot;7. storage、memory、calldata 是什么？&quot;">​</a></h3><p><strong>记忆方式：</strong> storage 像持久柜子，memory 像一次调用用的草稿纸，calldata 像调用时带来的只读入参。</p><p>更精确地说：它们是 Solidity 的数据位置概念。修改 <code>storage</code> 引用指向的结构体字段会影响链上状态；<code>memory</code> 是临时数据；<code>calldata</code> 通常用于外部调用的只读参数。</p><h3 id="_8-mapping-为什么不能像-python-dict-一样列出所有-key" tabindex="-1">8. mapping 为什么不能像 Python dict 一样列出所有 key？ <a class="header-anchor" href="#_8-mapping-为什么不能像-python-dict-一样列出所有-key" aria-label="Permalink to &quot;8. mapping 为什么不能像 Python dict 一样列出所有 key？&quot;">​</a></h3><p>Solidity mapping 没有直接暴露可枚举键集合的机制。你可以按某个 key 查询，但要显示所有用户，通常需要设计额外列表或使用事件加链下索引。</p><p><strong>常见误区：</strong> 不能把 mapping 当成 MySQL 表并写“遍历所有用户”的无限循环，不受限循环可能使交易耗尽 Gas。</p><p>练习入口：<a href="/01-solidity/storage-events">数据存储与事件</a>。</p><h2 id="第三组-权限与安全-必须知道反面案例" tabindex="-1">第三组：权限与安全（必须知道反面案例） <a class="header-anchor" href="#第三组-权限与安全-必须知道反面案例" aria-label="Permalink to &quot;第三组：权限与安全（必须知道反面案例）&quot;">​</a></h2><h3 id="_9-msg-sender-和-tx-origin-有何不同" tabindex="-1">9. msg.sender 和 tx.origin 有何不同？ <a class="header-anchor" href="#_9-msg-sender-和-tx-origin-有何不同" aria-label="Permalink to &quot;9. msg.sender 和 tx.origin 有何不同？&quot;">​</a></h3><p><code>msg.sender</code> 是当前这一层函数调用的<strong>直接调用者</strong>。用户直接调用 B 时是用户地址；用户调用 A、A 再调用 B 时，B 看到的 <code>msg.sender</code> 是 A。</p><p><code>tx.origin</code> 代表交易最初的外部账户。把它简单当权限判断依据，可能在复杂调用链里产生安全问题。</p><p>练习入口：<a href="/00-start/backend-map">从 Flask 迁移到合约</a>。</p><h3 id="_10-revert-会让失败交易完全免费吗" tabindex="-1">10. revert 会让失败交易完全免费吗？ <a class="header-anchor" href="#_10-revert-会让失败交易完全免费吗" aria-label="Permalink to &quot;10. revert 会让失败交易完全免费吗？&quot;">​</a></h3><p>不会。<code>revert</code> 会撤销本次 EVM 交易内已经做的链上状态更新及对应日志效果，但执行耗掉的 Gas 一般不能完全退回。</p><p><strong>特殊情况：</strong> 如果本地模拟提前发现失败，客户端可能根本没广播正式交易；不要把所有弹窗错误都当成链上失败交易。</p><h3 id="_11-什么是重入攻击" tabindex="-1">11. 什么是重入攻击？ <a class="header-anchor" href="#_11-什么是重入攻击" aria-label="Permalink to &quot;11. 什么是重入攻击？&quot;">​</a></h3><p>一个合约调用不可信外部合约时，对方可能在原函数结束前再次调用回来。如果原合约还没更新“已付款/余额归零”的状态，攻击者可能利用旧状态走重复路径。</p><p><strong>防范思路：</strong> Checks → Effects → Interactions（CEI），先检查，先更新内部状态，最后调用外部合约。但复杂跨函数/跨合约风险还需要额外分析。</p><p>练习入口：<a href="/04-security/">重入风险与 CEI</a>。</p><h3 id="_12-为什么-只有-owner-才能调用-还不等于安全" tabindex="-1">12. 为什么“只有 owner 才能调用”还不等于安全？ <a class="header-anchor" href="#_12-为什么-只有-owner-才能调用-还不等于安全" aria-label="Permalink to &quot;12. 为什么“只有 owner 才能调用”还不等于安全？&quot;">​</a></h3><p>因为 owner 私钥也可能被盗，收款地址也可能拒收，资金可能因业务规则卡住。安全不仅是权限检查，还包括资产去向、失败恢复、时间边界、外部依赖和用户恶意行为。</p><h2 id="第四组-工程、代币与综合项目" tabindex="-1">第四组：工程、代币与综合项目 <a class="header-anchor" href="#第四组-工程、代币与综合项目" aria-label="Permalink to &quot;第四组：工程、代币与综合项目&quot;">​</a></h2><h3 id="_13-abi、字节码、合约地址是什么关系" tabindex="-1">13. ABI、字节码、合约地址是什么关系？ <a class="header-anchor" href="#_13-abi、字节码、合约地址是什么关系" aria-label="Permalink to &quot;13. ABI、字节码、合约地址是什么关系？&quot;">​</a></h3><ul><li><strong>Solidity 源码</strong>：开发者写的程序。</li><li><strong>字节码 Bytecode</strong>：编译后由 EVM 执行的代码。</li><li><strong>ABI</strong>：描述外部可调用函数和事件的接口信息。</li><li><strong>合约地址</strong>：定位某个已部署合约实例的链上地址。</li></ul><p><strong>容易混淆：</strong> 只有 ABI 不能唯一确定实际调用哪个合约；还需要网络和合约地址。</p><p>练习入口：<a href="/02-evm/abi">ABI 与调用</a>。</p><h3 id="_14-erc-20-里的-approve-和-transferfrom-有何区别" tabindex="-1">14. ERC-20 里的 approve 和 transferFrom 有何区别？ <a class="header-anchor" href="#_14-erc-20-里的-approve-和-transferfrom-有何区别" aria-label="Permalink to &quot;14. ERC-20 里的 approve 和 transferFrom 有何区别？&quot;">​</a></h3><p><code>approve</code> 是设置某个 spender 可以使用多少额度；<code>transferFrom</code> 是被授权方按代币合约规则实际发起代币转移。</p><p>“授权成功”不等于“已经转账”。给陌生 DApp 无限授权可能带来资产风险。</p><p>练习入口：<a href="/04-security/erc20">ERC-20 基础</a>。</p><h3 id="_15-escrow-项目有哪些不能用真钱的原因" tabindex="-1">15. Escrow 项目有哪些不能用真钱的原因？ <a class="header-anchor" href="#_15-escrow-项目有哪些不能用真钱的原因" aria-label="Permalink to &quot;15. Escrow 项目有哪些不能用真钱的原因？&quot;">​</a></h3><p>至少指出以下三点：</p><ol><li><strong>没有现实世界交付证明和争议仲裁</strong>：买家可能收到货却在到期时退款。</li><li><strong>收款方拒收会导致 release 失败</strong>：钱不会凭空消失，但业务可能卡住。</li><li><strong>缺少生产级设计与专业安全审计</strong>：密钥恢复、风险管理、升级与监控均未完善。</li></ol><p>不能用“我自己写了 10 多条测试”就宣称已经通过安全审计。</p><p>练习入口：<a href="/05-project/escrow">Escrow 全部源码</a> · <a href="/05-project/acceptance">测试与验收</a>。</p><h2 id="一份五分钟自我介绍的参考组织方式" tabindex="-1">一份五分钟自我介绍的参考组织方式 <a class="header-anchor" href="#一份五分钟自我介绍的参考组织方式" aria-label="Permalink to &quot;一份五分钟自我介绍的参考组织方式&quot;">​</a></h2><p>不要照着术语念，把内容讲成一次真实开发过程：</p><blockquote><p>我做了一个本地测试用的 ETH 托管合约。先把买家、卖家以及 Funded、Delivered、Released、Refunded 四个状态定义清楚，再用 Solidity 限制每一步的权限。写转账函数时遵守先修改状态、再向外部地址转账的顺序，以降低典型重入风险。随后使用 Foundry 模拟买家、卖家和陌生人，验证越权、提前退款、重复结算、收款方拒收等场景。项目没有争议仲裁和专业审计，因此只能用于学习与测试环境。</p></blockquote><p>自己试着把这段讲给不懂区块链的朋友听；对方如果问“Gas 是什么”，你还能举出一个生活例子，就说明你不是单纯背诵。</p><h2 id="这份自测怎样才算完成" tabindex="-1">这份自测怎样才算完成？ <a class="header-anchor" href="#这份自测怎样才算完成" aria-label="Permalink to &quot;这份自测怎样才算完成？&quot;">​</a></h2><ul><li>能独立回答前 8 题，且不混淆钱包与链上余额。</li><li>能解释 <strong>msg.sender、revert 和重入</strong>，并指出源码里的相应位置。</li><li>能运行至少一条正向测试和一条期望失败的测试。</li><li>能明确说出项目尚未解决的真实商业问题。</li></ul><p>没达到就回去重新运行相应实验。<strong>学习以自己能复现与解释为准，不以读完页数为准。</strong></p>',68)])])}const u=a(i,[["render",l]]);export{g as __pageData,u as default};
